"use client";

import React from 'react';
import { cn } from '@/lib/utils';
import { GlowingEffect } from './glowing-effect';

// ============================================================================
// Table Container
// ============================================================================

interface TableProps extends React.HTMLAttributes<HTMLTableElement> {
  glowEffect?: boolean;
}

export function Table({ className, glowEffect = false, children, ...props }: TableProps) {
  return (
    <div className="relative">
      <div className="relative rounded-xl border border-[#B87333]/30 bg-slate-900/60 backdrop-blur-sm">
        {glowEffect && (
          <GlowingEffect
            proximity={60}
            spread={150}
            blur={10}
            borderWidth={2}
          />
        )}
        <div className="relative z-10 overflow-x-auto">
          <table className={cn('w-full text-sm', className)} {...props}>
            {children}
          </table>
        </div>
      </div>
    </div>
  );
}

// ============================================================================
// Table Header
// ============================================================================

interface TableHeaderProps extends React.HTMLAttributes<HTMLTableSectionElement> {
  glowEffect?: boolean;
}

export function TableHeader({ className, glowEffect = false, children, ...props }: TableHeaderProps) {
  return (
    <thead className={cn('bg-slate-800/50 relative', className)} {...props}>
      {children}
      {/* Bottom border with glow effect */}
      <tr aria-hidden="true" className="h-0">
        <th colSpan={100} className="p-0 h-[1px] relative">
          <div className="absolute inset-x-0 bottom-0 h-[1px] bg-[#B87333]/30" />
          {glowEffect && <HeaderBorderGlow />}
        </th>
      </tr>
    </thead>
  );
}

// Header border glow component
function HeaderBorderGlow() {
  const containerRef = React.useRef<HTMLDivElement>(null);
  const [isHovered, setIsHovered] = React.useState(false);
  const [glowX, setGlowX] = React.useState(0);

  React.useEffect(() => {
    const handleMouseMove = (e: MouseEvent) => {
      if (!containerRef.current) return;

      const rect = containerRef.current.getBoundingClientRect();
      const isNear =
        e.clientX >= rect.left - 60 &&
        e.clientX <= rect.right + 60 &&
        e.clientY >= rect.top - 40 &&
        e.clientY <= rect.bottom + 40;

      setIsHovered(isNear);
      if (isNear) {
        setGlowX(e.clientX - rect.left);
      }
    };

    window.addEventListener("mousemove", handleMouseMove);
    return () => window.removeEventListener("mousemove", handleMouseMove);
  }, []);

  return (
    <div
      ref={containerRef}
      className="absolute inset-x-0 bottom-0 h-[3px] pointer-events-none overflow-hidden"
    >
      <div
        className="absolute h-full transition-opacity duration-300"
        style={{
          width: "120px",
          left: glowX - 60,
          background: "radial-gradient(ellipse 60px 3px at center, #DA8A67, #B87333 40%, transparent 70%)",
          opacity: isHovered ? 1 : 0,
          filter: "blur(2px)",
        }}
      />
    </div>
  );
}

// ============================================================================
// Table Body
// ============================================================================

interface TableBodyProps extends React.HTMLAttributes<HTMLTableSectionElement> {}

export function TableBody({ className, children, ...props }: TableBodyProps) {
  return (
    <tbody className={cn('divide-y divide-[#B87333]/20', className)} {...props}>
      {children}
    </tbody>
  );
}

// ============================================================================
// Table Row
// ============================================================================

interface TableRowProps extends React.HTMLAttributes<HTMLTableRowElement> {
  isClickable?: boolean;
}

export function TableRow({ className, isClickable, children, ...props }: TableRowProps) {
  return (
    <tr
      className={cn(
        'transition-colors',
        isClickable && 'cursor-pointer hover:bg-slate-800/50',
        className
      )}
      {...props}
    >
      {children}
    </tr>
  );
}

// ============================================================================
// Table Head Cell
// ============================================================================

interface TableHeadProps extends React.ThHTMLAttributes<HTMLTableCellElement> {}

export function TableHead({ className, children, ...props }: TableHeadProps) {
  return (
    <th
      className={cn(
        'px-4 py-3 text-left text-xs font-semibold uppercase tracking-wider text-slate-400',
        className
      )}
      {...props}
    >
      {children}
    </th>
  );
}

// ============================================================================
// Table Cell
// ============================================================================

interface TableCellProps extends React.TdHTMLAttributes<HTMLTableCellElement> {}

export function TableCell({ className, children, ...props }: TableCellProps) {
  return (
    <td className={cn('px-4 py-3 text-slate-300', className)} {...props}>
      {children}
    </td>
  );
}

// ============================================================================
// Empty State
// ============================================================================

interface TableEmptyStateProps {
  icon?: React.ReactNode;
  title: string;
  description?: string;
  action?: React.ReactNode;
}

export function TableEmptyState({ icon, title, description, action }: TableEmptyStateProps) {
  return (
    <tr>
      <td colSpan={100}>
        <div className="flex flex-col items-center justify-center py-12 text-center">
          {icon && <div className="mb-4 text-slate-400">{icon}</div>}
          <h3 className="text-sm font-medium text-white">{title}</h3>
          {description && <p className="mt-1 text-sm text-slate-400">{description}</p>}
          {action && <div className="mt-4">{action}</div>}
        </div>
      </td>
    </tr>
  );
}
