"use client";

import { memo, useCallback, useEffect, useRef, useState } from "react";
import { cn } from "@/lib/utils";

interface GlowingEffectProps {
  blur?: number;
  proximity?: number;
  spread?: number;
  className?: string;
  disabled?: boolean;
  borderWidth?: number;
}

const GlowingEffect = memo(
  ({
    blur = 4,
    proximity = 100,
    spread = 100,
    className,
    borderWidth = 2,
    disabled = false,
  }: GlowingEffectProps) => {
    const containerRef = useRef<HTMLDivElement>(null);
    const [isHovered, setIsHovered] = useState(false);
    const [glowStyle, setGlowStyle] = useState({ x: 0, y: 0 });

    const handleMouseMove = useCallback(
      (e: MouseEvent) => {
        if (!containerRef.current || disabled) return;

        const rect = containerRef.current.getBoundingClientRect();

        // Check if mouse is within proximity
        const isNear =
          e.clientX >= rect.left - proximity &&
          e.clientX <= rect.right + proximity &&
          e.clientY >= rect.top - proximity &&
          e.clientY <= rect.bottom + proximity;

        setIsHovered(isNear);

        if (isNear) {
          const x = e.clientX - rect.left;
          const y = e.clientY - rect.top;
          setGlowStyle({ x, y });
        }
      },
      [proximity, disabled]
    );

    useEffect(() => {
      if (disabled) return;

      window.addEventListener("mousemove", handleMouseMove);
      return () => window.removeEventListener("mousemove", handleMouseMove);
    }, [handleMouseMove, disabled]);

    if (disabled) return null;

    return (
      <div
        ref={containerRef}
        className={cn(
          "pointer-events-none absolute -inset-[1px] rounded-[inherit]",
          className
        )}
        style={{
          background: isHovered
            ? `radial-gradient(${spread}px circle at ${glowStyle.x}px ${glowStyle.y}px, #DA8A67, #B87333 40%, transparent 70%)`
            : "transparent",
          padding: borderWidth,
          WebkitMask: "linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0)",
          WebkitMaskComposite: "xor",
          maskComposite: "exclude",
          filter: blur > 0 ? `blur(${blur}px)` : undefined,
          transition: "opacity 0.3s ease",
          opacity: isHovered ? 1 : 0,
        }}
      />
    );
  }
);

GlowingEffect.displayName = "GlowingEffect";

export { GlowingEffect };
